<?php
$title='Team & Roles';$subtitle='Who can use Setu and what each person can do';
$rows=DB::all("SELECT u.*,(SELECT COUNT(*) FROM leads l WHERE l.assigned_to=u.id AND l.is_lead=1 AND l.status NOT IN ('won','lost')) open_n,(SELECT COUNT(*) FROM leads l WHERE l.assigned_to=u.id AND l.status='won') won_n FROM users u ORDER BY u.active DESC,FIELD(u.role,'super','admin','sales'),u.name");
$cnt=array_count_values(array_column(array_filter($rows,fn($u)=>$u['active']),'role'));
$rc=['super'=>'violet','admin'=>'blue','sales'=>'green'];
$perm=['super'=>['Switch modules on/off','Manage all users incl. super admins','All settings, API keys & usage','Everything admins can do'],'admin'=>['All leads, assign owners, import/export','Prospecting: scraper, audits, reports','Automations, templates, AI & settings','Add admins and sales people'],'sales'=>['Own leads + unassigned leads','Add leads, notes, status, follow-ups','Book appointments, log calls & replies','No settings, exports or deletes']];
?>
<div class="stats"><?=kpi('Active users',count(array_filter($rows,fn($u)=>$u['active'])),'users','indigo',count($rows).' in total')?><?=kpi('Super admins',$cnt['super']??0,'shield','violet','full control')?><?=kpi('Admins / managers',$cnt['admin']??0,'user','blue','run the team')?><?=kpi('Sales people',$cnt['sales']??0,'target','green','work their leads')?></div>
<div class="g31"><?php foreach(roles() as $k=>[$lb,,$ds]):?><div class="card c-<?=$rc[$k]?>"><div class="au-card"><span class="hi"><?=icon($k==='super'?'shield':($k==='admin'?'user':'target'))?></span><div><b><?=e($lb)?></b><p class="hint mt0" style="margin-top:2px"><?=e($ds)?></p></div></div><ul class="ul"><?php foreach($perm[$k] as $p):?><li><?=e($p)?></li><?php endforeach?></ul></div><?php endforeach?></div>
<div class="card p0"><div class="card-h"><h3><span class="hi c-blue"><?=icon('users')?></span>Team members</h3><a class="btn btn-p btn-sm" href="<?=url('user',['id'=>'new'])?>"><?=icon('plus')?>Add team member</a></div><div class="tw"><table class="tbl"><thead><tr><th class="sn">#</th><th>Person</th><th>Role</th><th>Status</th><th class="num">Open leads</th><th class="num">Won</th><th>Last sign-in</th><th></th></tr></thead><tbody><?php $sn=0;foreach($rows as $u):$sn++;$me=(int)$u['id']===(int)user()['id'];$edit=is_super()||$u['role']!=='super';?><tr style="<?=$u['active']?'':'opacity:.55'?>"><td class="sn"><?=$sn?></td><td><div class="who"><span class="av"><?=e(mb_strtoupper(mb_substr($u['name'],0,1)))?></span><div class="biz"><b><?=e($u['name'])?><?=$me?' <span class="bdg c-gray sm">You</span>':''?></b><small><?=e($u['email'])?><?=$u['phone']?' · '.e($u['phone']):''?></small></div></div></td><td><?=rbadge($u['role'])?></td><td><?=$u['active']?'<span class="bdg c-green bdg-dot">Active</span>':'<span class="bdg c-gray">Deactivated</span>'?></td><td class="num"><a class="lnk" href="<?=url('leads',['own'=>$u['id']])?>"><?=(int)$u['open_n']?></a></td><td class="num"><?=(int)$u['won_n']?></td><td class="muted sm nowrap"><?=$u['last_login']?ago($u['last_login']):'Never'?></td><td class="act"><?php if($edit):?><a class="btn btn-sm" href="<?=url($me?'account':'user',['id'=>$u['id']])?>"><?=icon('edit')?>Edit</a><?php else:?><span class="muted xs">Super admin only</span><?php endif?></td></tr><?php endforeach?></tbody></table></div></div>
